INSERT INTO event_translations(event_id,locale,title,summary,status,time_label) VALUES
('69000000-0000-4000-8000-000000000001','zh-CN','雅典娜·帕特农像委托与制作','雅典卫城重建计划中的大型神像委托与制作。','published','约公元前 447–438 年'),('69000000-0000-4000-8000-000000000001','en','Commission and making of Athena Parthenos','The commission and making of the cult statue within the rebuilding programme of the Acropolis.','published','c. 447–438 BCE'),
('69000000-0000-4000-8000-000000000002','zh-CN','斯克罗威尼礼拜堂壁画周期','乔托及其工坊在帕多瓦完成的壁画周期。','published','约 1303–1305 年'),('69000000-0000-4000-8000-000000000002','en','Scrovegni Chapel fresco cycle','Giotto and his workshop complete a fresco cycle in Padua.','published','c. 1303–1305 CE'),
('69000000-0000-4000-8000-000000000003','zh-CN','《蒙娜丽莎》持续创作','列奥纳多在多年间持续修改这幅肖像，年代范围以馆藏目录为准。','published','1503–1519 年间'),('69000000-0000-4000-8000-000000000003','en','Leonardo works on the Mona Lisa','Leonardo works on the portrait over several years; the range follows the collection record.','published','1503–1519'),
('69000000-0000-4000-8000-000000000004','zh-CN','《夜巡》完成','伦勃朗为阿姆斯特丹民兵团完成大型集体肖像。','published','1642 年'),('69000000-0000-4000-8000-000000000004','en','The Night Watch completed','Rembrandt completes a large civic group portrait for Amsterdam''s militia company.','published','1642'),
('69000000-0000-4000-8000-000000000005','zh-CN','《星月夜》创作','梵高在圣雷米时期完成这幅结合观察与想象的夜景。','published','1889 年 6 月'),('69000000-0000-4000-8000-000000000005','en','The Starry Night painted','Van Gogh paints the night scene at Saint-Rémy, combining observation and imagination.','published','June 1889') ON CONFLICT DO NOTHING;
